/* Panel de contenido de MSG-01 · Lista de Hilos.
   Solo tokens del sistema de diseño leídos como variables CSS: ningún hex, ningún
   rgb(). Donde el mock pide blanco puro y no hay token de blanco, se usa el claro
   más cercano (--bw-surface-mist / --bw-cold-white). */

.screen {
  display: flex;
  flex-direction: column;
  min-width: 0;
}

.eyebrow {
  margin: 0 0 4px;
  font-family: var(--bw-font-title);
  font-size: var(--bw-size-eyebrow);
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: var(--bw-ls-eyebrow);
  color: var(--bw-steel-mist);
}

.title {
  margin: 0 0 3px;
  font-family: var(--bw-font-title);
  font-size: var(--bw-size-title);
  font-weight: 700;
  letter-spacing: var(--bw-ls-title);
  color: var(--bw-deep-steel);
}

.sub {
  margin: 0 0 16px;
  max-width: 560px;
  font-size: var(--bw-size-body);
  line-height: 1.6;
  color: var(--bw-steel-mist);
}

/* Aviso E2EE: bloque brass informativo, sin botón. */
.e2ee {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  align-self: flex-start;
  margin-bottom: 14px;
  padding: 6px 10px;
  background: var(--bw-tag-bg);
  border: 1px solid var(--bw-tag-border);
  border-radius: var(--bw-radius);
  font-family: var(--bw-font-mono);
  font-size: var(--bw-size-hint);
  text-transform: uppercase;
  letter-spacing: var(--bw-ls-divider);
  color: var(--bw-brass);
}

.actionsBar {
  display: flex;
  align-items: center;
  gap: 10px;
  margin-bottom: 14px;
  flex-wrap: wrap;
}

.searchWrap {
  position: relative;
  flex: 1;
  max-width: 300px;
}

.searchWrap i {
  position: absolute;
  left: 10px;
  top: 50%;
  transform: translateY(-50%);
  font-size: 15px;
  color: var(--bw-input-placeholder);
}

.searchInput {
  width: 100%;
  height: 36px;
  padding: 0 10px 0 32px;
  background: var(--bw-surface-mist);
  border: 1px solid var(--bw-line-steel-strong);
  border-radius: var(--bw-radius);
  color: var(--bw-input-text);
  font-family: var(--bw-font-body);
  font-size: var(--bw-size-input);
  outline: none;
}

.searchInput:focus {
  border-color: var(--bw-calibration-blue);
  box-shadow: var(--bw-focus-halo);
}

.searchInput::placeholder {
  color: var(--bw-input-placeholder);
}

.primaryBtn {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  height: 36px;
  padding: 0 18px;
  background: var(--bw-calibration-blue);
  border: none;
  border-radius: var(--bw-radius);
  color: var(--bw-cold-white);
  font-family: var(--bw-font-body);
  font-size: var(--bw-size-input);
  font-weight: 500;
  white-space: nowrap;
  cursor: pointer;
}

/* Apagado porque DIR-01 no está en el alcance: se dice con el estado del control,
   no con un badge verde que prometa una pantalla que no existe. */
.primaryBtn:disabled {
  background: var(--bw-cold-white);
  border: 1px solid var(--bw-line-steel-strong);
  color: var(--bw-input-placeholder);
  cursor: not-allowed;
}

.scopeNote {
  max-width: 230px;
  font-size: var(--bw-size-label);
  line-height: 1.3;
  color: var(--bw-warning-dark);
}

.counter {
  margin-left: auto;
  font-size: var(--bw-size-label);
  color: var(--bw-input-placeholder);
  white-space: nowrap;
}

.error {
  margin-bottom: 14px;
  padding: 10px 12px;
  background: var(--bw-sensitive-bg);
  border: 1px solid var(--bw-badge-danger-border);
  border-radius: var(--bw-radius);
  color: var(--bw-error-text);
  font-size: var(--bw-size-input);
  line-height: 1.5;
}

.loading {
  margin: 0 0 14px;
  font-size: var(--bw-size-input);
  color: var(--bw-steel-mist);
}

.pagination {
  display: flex;
  align-items: center;
  gap: 4px;
  margin-top: 14px;
}

.page {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 30px;
  height: 30px;
  padding: 0 8px;
  background: var(--bw-surface-mist);
  border: 1px solid var(--bw-line-steel-strong);
  border-radius: var(--bw-radius);
  color: var(--bw-ink-steel);
  font-family: var(--bw-font-body);
  font-size: var(--bw-size-label);
  cursor: pointer;
  transition: color 0.12s, border-color 0.12s;
}

.page:hover:not(:disabled) {
  border-color: var(--bw-brass);
  color: var(--bw-brass);
}

.page:disabled {
  color: var(--bw-hint-steel);
  cursor: default;
}

.pageActive,
.pageActive:hover {
  background: var(--bw-deep-steel);
  border-color: var(--bw-deep-steel);
  color: var(--bw-cold-white);
  cursor: default;
}

