import { useEffect, useState } from 'react';
import type { MemberProfile } from '../../lib/session';
import { fetchThreadPage, pageCount, type ThreadSummary } from '../../lib/threads';
import { ThreadList } from './ThreadList';
import styles from './Messages.module.css';

/**
 * MSG-01 · Lista de Hilos. **La pantalla**, no un componente de presentación:
 * llama a `fetchThreadPage` con el `orgId` de la sesión y es dueña del estado de
 * búsqueda y de página. El shell (marca, nav, sidebar, VERA) ya existe y no se
 * toca desde aquí.
 *
 * Lo que el mock aprueba y el MVP **no** tiene no se reproduce como si
 * funcionara: no hay aviso E2EE con botón de passphrase (las claves viven en
 * memoria de sesión y no hay frase de seguridad), no hay punto azul ni recuento
 * de no leídos (el esquema no guarda ningún estado de lectura: no hay de dónde
 * sacar el número), no hay contador de los 25 hilos diarios y `Nuevo contacto`
 * abre DIR-01, que está fuera del alcance (Plan §9).
 */

interface Props {
  profile: MemberProfile;
  /**
   * Inyectable para que los tests no dependan del reloj. Se declara
   * `Date | undefined` y no `Date` (F-137): con `exactOptionalPropertyTypes`, un
   * `now` que llegue `undefined` a `ThreadList` no compila aunque `relativeTime`
   * tenga su propio `new Date()` de respaldo.
   */
  now?: Date | undefined;
  /**
   * Firma pública del componente (F-118), cableada por el shell en `App.tsx`
   * después de escribirse esta tarea. MSG-02 no existe, así que abrir un hilo no
   * lleva a ningún sitio: **se declara y se ignora**. Sin la declaración el repo
   * no compila por un fichero que esta tarea no escribe.
   */
  onOpenThread?: (threadId: string) => void;
}

/**
 * El texto del error de verdad (F-128).
 *
 * No se captura siempre un `Error`: PostgREST rechaza con un objeto plano
 * `{ code, message }`, así que `String(e)` daría `[object Object]` y `e.message`
 * daría `undefined`. Es F-020 palabra por palabra — la pantalla enseñaba
 * `[object Object]` mientras el `PGRST201` explicaba el fallo entero.
 */
function describeError(e: unknown): string {
  if (e instanceof Error && e.message !== '') return e.message;

  if (typeof e === 'object' && e !== null) {
    const detail = e as { code?: unknown; message?: unknown };
    const parts: string[] = [];
    if (typeof detail.code === 'string' && detail.code !== '') parts.push(detail.code);
    if (typeof detail.message === 'string' && detail.message !== '') parts.push(detail.message);
    if (parts.length > 0) return parts.join(' · ');
  }

  return String(e);
}

export function Messages({ profile, now }: Props) {
  /** Lo que hay escrito en el input. Solo se aplica al pulsar Enter. */
  const [draft, setDraft] = useState('');
  /** La búsqueda aplicada: es la que viaja a la consulta. */
  const [search, setSearch] = useState('');
  const [page, setPage] = useState(1);

  const [threads, setThreads] = useState<ThreadSummary[]>([]);
  const [total, setTotal] = useState(0);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  const orgId = profile.orgId;
  /** El reloj inyectable, con `new Date()` por defecto. */
  const clock = now ?? new Date();

  useEffect(() => {
    let alive = true;
    setLoading(true);
    setError(null);

    fetchThreadPage({ orgId, search, page })
      .then((res) => {
        if (!alive) return;
        setThreads(res.threads);
        setTotal(res.total);
        setLoading(false);
      })
      .catch((e: unknown) => {
        if (!alive) return;
        setThreads([]);
        setTotal(0);
        setError(describeError(e));
        setLoading(false);
      });

    return () => {
      alive = false;
    };
  }, [orgId, search, page]);

  const totalPages = pageCount(total);
  const pages: number[] = [];
  for (let n = 1; n <= totalPages; n += 1) pages.push(n);

  function handleOpen(): void {
    // MSG-02 no está entre las 8 pantallas del alcance (Plan §9): abrir un hilo
    // todavía no lleva a ningún sitio. La fila avisa con su ID y aquí no pasa
    // nada más; `onOpenThread` se ignora a propósito (F-118).
  }

  return (
    <section className={styles.screen}>
      <p className={styles.eyebrow}>Módulo 04 · Mensajería E2EE</p>
      <h1 className={styles.title}>Hilos</h1>
      <p className={styles.sub}>
        Tus conversaciones con otros distribuidores. Todo el contenido está cifrado de extremo a
        extremo.
      </p>

      {/* Barra informativa, sin acción: en el MVP no hay frase de seguridad que
          introducir, así que el botón del mock no se pinta como disponible. */}
      <div className={styles.e2ee}>
        <i className="ti ti-lock" aria-hidden="true" />
        E2EE activo · claves en memoria de sesión · contenido descifrado localmente
      </div>

      <div className={styles.actionsBar}>
        <div className={styles.searchWrap}>
          <i className="ti ti-search" aria-hidden="true" />
          <input
            type="text"
            className={styles.searchInput}
            value={draft}
            placeholder="Buscar por nombre de organización..."
            aria-label="Buscar por nombre de organización"
            onChange={(e) => setDraft(e.target.value)}
            onKeyDown={(e) => {
              if (e.key !== 'Enter') return;
              e.preventDefault();
              setSearch(draft.trim());
              setPage(1);
            }}
          />
        </div>

        <button
          type="button"
          className={styles.primaryBtn}
          disabled
          aria-describedby="directorio-scope"
        >
          <i className="ti ti-address-book" aria-hidden="true" />
          Nuevo contacto
        </button>
        {/* El motivo, visible, junto al botón apagado y en su propio nodo (F-139). */}
        <span data-testid="directorio-scope" id="directorio-scope" className={styles.scopeNote}>
          El Directorio está fuera del MVP.
        </span>

        <span data-testid="pag-info" className={styles.counter}>
          {total} hilos · Página {page} de {totalPages}
        </span>
      </div>

      {error !== null ? (
        <div role="alert" className={styles.error}>
          No se pudieron cargar los hilos. {error}
        </div>
      ) : null}

      {loading ? <p className={styles.loading}>Cargando hilos…</p> : null}

      {!loading && error === null ? (
        <ThreadList threads={threads} now={clock} onOpen={handleOpen} />
      ) : null}

      <nav className={styles.pagination} aria-label="Paginación de hilos">
        <button
          type="button"
          className={styles.page}
          aria-label="Página anterior"
          disabled={page <= 1}
          onClick={() => setPage(page - 1)}
        >
          ‹
        </button>
        {pages.map((n) => (
          // El número va como TEXTO y sin `aria-label`: un `aria-label` sustituye
          // al nombre accesible y `getByRole('button', { name: '2' })` dejaría de
          // encontrar la página (F-145).
          <button
            key={n}
            type="button"
            className={n === page ? `${styles.page} ${styles.pageActive}` : styles.page}
            onClick={() => setPage(n)}
          >
            {n}
          </button>
        ))}
        <button
          type="button"
          className={styles.page}
          aria-label="Página siguiente"
          disabled={page >= totalPages}
          onClick={() => setPage(page + 1)}
        >
          ›
        </button>
      </nav>
    </section>
  );
}

