/* Lista de hilos de MSG-01.
   Todo el color sale de los tokens del sistema de diseño
   (openspec/architecture/design-system.md §1) leídos como variables CSS. Donde el
   HTML aprobado pide blanco puro y el sistema no tiene un token de blanco, se usa
   el claro más cercano (--bw-surface-mist) y se dice aquí: un hex sería un color
   fuera de la paleta y §6.1 lo prohíbe. */

.list {
  list-style: none;
  margin: 0;
  padding: 0;
  background: var(--bw-surface-mist);
  border: 1px solid var(--bw-line-steel);
  border-radius: var(--bw-radius);
  overflow: hidden;
}

.row {
  border-bottom: 1px solid var(--bw-divider-mist);
}

.row:last-child {
  border-bottom: none;
}

/* La fila entera es el botón: mismo alto y mismo relleno que la fila del mock,
   pero sin `onclick` en un `<div>` con rol fingido. */
.rowBtn {
  display: grid;
  grid-template-columns: 1fr auto;
  align-items: center;
  gap: 4px 10px;
  width: 100%;
  padding: 14px 18px;
  background: none;
  border: none;
  text-align: left;
  font-family: var(--bw-font-body);
  cursor: pointer;
  transition: background 0.1s;
}

.rowBtn:hover {
  background: var(--bw-hover-surface);
}

.rowBtn:focus-visible {
  outline: none;
  box-shadow: var(--bw-focus-halo);
}

.orgCell {
  display: flex;
  align-items: center;
  gap: 8px;
  min-width: 0;
}

.org {
  /* El mock pide 14px para el nombre de la organización; el único paso de 14px
     del sistema es el token de eyebrow, así que se reutiliza en vez de inventar
     un tamaño nuevo. */
  font-size: var(--bw-size-eyebrow);
  font-weight: 500;
  color: var(--bw-deep-steel);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.country {
  font-family: var(--bw-font-mono);
  font-size: var(--bw-size-hint);
  color: var(--bw-steel-mist);
  background: var(--bw-cold-white);
  border: 1px solid var(--bw-line-steel);
  border-radius: var(--bw-radius);
  padding: 1px 6px;
  white-space: nowrap;
}

.ts {
  font-family: var(--bw-font-mono);
  font-size: var(--bw-size-hint);
  color: var(--bw-steel-mist);
  white-space: nowrap;
  justify-self: end;
}

.preview {
  font-size: var(--bw-size-label);
  color: var(--bw-steel-mist);
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.state {
  font-family: var(--bw-font-mono);
  font-size: var(--bw-size-hint);
  font-weight: 500;
  text-transform: uppercase;
  letter-spacing: var(--bw-ls-label);
  padding: 2px 7px;
  border-radius: var(--bw-radius);
  white-space: nowrap;
  justify-self: end;
}

/* Los cinco tonos de `stateTone`, con los mismos colores que la spec §3 da en
   hex: el hex se queda en el token, aquí solo se elige cuál. */
.neutral {
  background: var(--bw-badge-neutral-bg);
  color: var(--bw-steel-mist);
  border: 1px solid var(--bw-badge-neutral-border);
}

.info {
  background: var(--bw-chip-active-bg);
  color: var(--bw-calibration-blue);
  border: 1px solid var(--bw-chip-active-border);
}

.warn {
  background: var(--bw-badge-warning-bg);
  color: var(--bw-warning);
  border: 1px solid var(--bw-badge-warning-border);
}

.success {
  background: var(--bw-badge-success-bg);
  color: var(--bw-signal-green);
  border: 1px solid var(--bw-badge-success-border);
}

.closed {
  background: var(--bw-badge-neutral-bg);
  color: var(--bw-input-placeholder);
  border: 1px solid var(--bw-badge-neutral-border-soft);
  text-decoration: line-through;
}

/* ── Estado vacío ─────────────────────────────────────────────────────────
   Fuera de cualquier `<ul>` (F-141): aquí no hay ni un `listitem`. */
.emptyState {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 12px;
  padding: 40px 24px;
  background: var(--bw-surface-mist);
  border: 1px solid var(--bw-line-steel);
  border-radius: var(--bw-radius);
  text-align: center;
}

.emptyText {
  margin: 0;
  max-width: 460px;
  font-size: var(--bw-size-body);
  color: var(--bw-ink-steel);
  line-height: 1.6;
}

.emptyWhy {
  margin: 0;
  font-size: var(--bw-size-label);
  color: var(--bw-warning-dark);
}

/* Botón primario y su versión apagada. El apagado no es decorativo: es la forma
   de decir "esto no lleva a ningún sitio" sin prometer lo que el MVP no tiene. */
.primaryBtn {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  height: 36px;
  padding: 0 18px;
  border: none;
  border-radius: var(--bw-radius);
  background: var(--bw-calibration-blue);
  color: var(--bw-cold-white);
  font-family: var(--bw-font-body);
  font-size: var(--bw-size-input);
  font-weight: 500;
  white-space: nowrap;
  cursor: pointer;
}

.primaryBtn:disabled {
  background: var(--bw-cold-white);
  border: 1px solid var(--bw-line-steel-strong);
  color: var(--bw-input-placeholder);
  cursor: not-allowed;
}

