import {
  previewLabel,
  relativeTime,
  stateTone,
  type StateTone,
  type ThreadSummary,
} from '../../lib/threads';
import styles from './ThreadList.module.css';

/**
 * Lista de hilos de MSG-01, escrita a mano.
 *
 * Presentacional y nada más: pinta las filas **en el orden que las recibe** —el
 * orden lo decide el servidor, `last_item_at` descendente en `threads.ts`— y al
 * abrir una avisa con el ID del hilo, nunca con el objeto. No carga datos ni
 * pagina: de eso se encarga `Messages.tsx`.
 *
 * La vista previa sale de `previewLabel`, que solo lee metadatos (`item_type` y
 * `part_number`): contenido descifrado aquí no hay ni puede haberlo (spec §7).
 */

/**
 * Tono → clase del módulo CSS.
 *
 * El tipo es `Record<StateTone, string | undefined>`, **no** `string` a secas: con
 * `noUncheckedIndexedAccess` activo cualquier acceso a `styles` puede no existir
 * en el `.module.css` y TypeScript lo tipa `string | undefined`, así que el
 * `Record<StateTone, string>` no compila (F-143). El hueco se resuelve en el
 * único punto de consumo, con `?? ''`, para que una clase que falte deje la fila
 * sin adorno en vez de escribir la palabra `undefined` en el atributo `class`.
 */
const TONE_CLASS: Record<StateTone, string | undefined> = {
  neutral: styles.neutral,
  info: styles.info,
  warn: styles.warn,
  success: styles.success,
  closed: styles.closed,
};

interface Props {
  threads: ThreadSummary[];
  /** Inyectable para que los tests no dependan del reloj. */
  now?: Date | undefined;
  onOpen: (id: string) => void;
}

export function ThreadList({ threads, now, onOpen }: Props) {
  // ── Estado vacío ───────────────────────────────────────────────────────────
  // Va en un contenedor aparte, NUNCA dentro de un `<ul>`: con la lista vacía el
  // contrato exige que no quede ningún `listitem` en el documento (F-141).
  if (threads.length === 0) {
    return (
      <div className={styles.emptyState}>
        {/* La frase entera, con su punto en medio, dentro de UN solo nodo de
            texto: `getByText` con una cadena compara el texto de un elemento, no
            el de un contenedor con hijos (F-147). */}
        <p className={styles.emptyText}>
          Todavía no tienes ninguna conversación. Usa el Directorio para contactar con otras organizaciones.
        </p>
        {/* Botón apagado a propósito y con su motivo al lado. El Directorio
            (DIR-01) no está entre las 8 pantallas del alcance (Plan §9): un botón
            que parece pulsable y no lleva a ningún sitio es CLAUDE.md §7 llevado
            a la interfaz (F-023 e / F-128). */}
        <button type="button" className={styles.primaryBtn} disabled>
          Ir al Directorio
        </button>
        <p className={styles.emptyWhy}>El Directorio está fuera del MVP.</p>
      </div>
    );
  }

  return (
    <ul className={styles.list}>
      {threads.map((t) => (
        <li key={t.id} className={styles.row}>
          {/* La fila es pulsable con un `<button>` DENTRO del `<li>`, nunca con un
              `role` encima: un `role` explícito SUSTITUYE al implícito, así que
              `<li role="button">` dejaría de ser `listitem` (F-131). Y es este
              botón, no el `<li>`, el que lleva el nombre accesible del hilo. */}
          <button type="button" className={styles.rowBtn} onClick={() => onOpen(t.id)}>
            <span className={styles.orgCell}>
              <span className={styles.org}>{t.counterpartyName}</span>
              {t.counterpartyCountry !== '' ? (
                <span className={styles.country}>{t.counterpartyCountry}</span>
              ) : null}
            </span>
            <span className={styles.ts}>{relativeTime(t.lastItemAt, now)}</span>
            <span className={styles.preview}>{previewLabel(t.lastItem)}</span>
            <span className={`${styles.state} ${TONE_CLASS[stateTone(t.state)] ?? ''}`}>
              {t.state}
            </span>
          </button>
        </li>
      ))}
    </ul>
  );
}
